test('get() returns initial value', () => {
  const sig = createSignal(42);
  expect(sig.get()).toBe(42);
});

test('set() updates the value', () => {
  const sig = createSignal(0);
  sig.set(99);
  expect(sig.get()).toBe(99);
});

test('subscribe listener is called on set', () => {
  const sig = createSignal('a');
  const calls: string[] = [];
  sig.subscribe(() => calls.push(sig.get()));
  sig.set('b');
  expect(calls).toEqual(['b']);
});

test('useSignal returns current signal value', () => {
  const sig = createSignal(7);
  const { result } = renderHook(() => useSignal(sig));
  expect(result.current).toBe(7);
});

test('useSignal re-renders when signal changes', () => {
  const sig = createSignal(0);
  const { result } = renderHook(() => useSignal(sig));
  act(() => sig.set(100));
  expect(result.current).toBe(100);
});

