  const calls: number[] = [];
  const unsub = sig.subscribe(() => calls.push(sig.get()));
  sig.set(1);
  unsub();
  sig.set(2);
  expect(calls).toEqual([1]);
});

solution:
import { useSyncExternalStore } from 'react';

export function createSignal<T>(initial: T) {
  let value = initial;
  const listeners = new Set<() => void>();

  const get = () => value;
  const set = (v: T) => {
    value = v;
    listeners.forEach(fn => fn());
  };
  const subscribe = (fn: () => void) => {
    listeners.add(fn);
    return () => listeners.delete(fn);
  };

  return { get, set, subscribe };
}

export function useSignal<T>(signal: ReturnType<typeof createSignal<T>>): T {
  return useSyncExternalStore(signal.subscribe, signal.get);
}
